/*
 * Feuille de l'application, écrite par OxoAI (gateway/application/app.css).
 * Les couleurs et les polices sont dans app/theme.css : c'est là qu'on change
 * l'allure. Mise en page d'un logiciel de gestion classique : barre du haut,
 * menu et filtres à gauche, liste au centre, détail à droite.
 */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
[hidden] { display: none !important; }
html, body { height: 100%; }
body {
  font-family: var(--police-texte);
  font-size: 14px;
  line-height: 1.5;
  color: var(--texte);
  background: var(--fond);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3 { font-family: var(--police-titre); color: var(--texte); line-height: 1.2; text-wrap: balance; }
h1 { font-size: 1.5rem; font-weight: 650; letter-spacing: -0.01em; }
h2 { font-size: 1rem; font-weight: 650; }
h3 { font-size: .875rem; font-weight: 650; }
a { color: var(--lien); }
button, input, select, textarea { font: inherit; color: inherit; }
:focus-visible { outline: 2px solid var(--anneau); outline-offset: 2px; }
.ic { width: 18px; height: 18px; flex: none; }
.attenue { color: var(--texte-attenue); }
.petit { font-size: .8125rem; }
.vide { color: var(--texte-attenue); }
.rangee { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem; }

/* ---------- Barre du haut ---------- */
.barre-haut {
  position: sticky; top: 0; z-index: 30;
  display: flex; align-items: center; gap: 1rem;
  height: 52px; padding: 0 1rem;
  background: var(--primaire); color: var(--sur-primaire);
  box-shadow: 0 1px 0 rgb(0 0 0 / .12);
}
.marque { display: flex; align-items: center; gap: .6rem; font-family: var(--police-titre); font-weight: 700; font-size: 1rem; letter-spacing: .01em; }
.marque__logo { width: 26px; height: 26px; border-radius: 7px; background: var(--sur-primaire); opacity: .92; box-shadow: inset 0 0 0 6px var(--primaire), inset 0 0 0 9px var(--sur-primaire); }
.barre-haut__droite { margin-left: auto; display: flex; align-items: center; gap: 1.25rem; font-size: .8125rem; }
.barre-haut__date::first-letter { text-transform: uppercase; }
.utilisateur { display: flex; align-items: center; gap: .5rem; font-weight: 600; }
.utilisateur__avatar { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--sur-primaire); color: var(--primaire); font-weight: 700; font-size: .75rem; }
.barre-haut__menu { display: none; color: var(--sur-primaire); background: transparent; border-color: transparent; }

/* ---------- Cadre ---------- */
.cadre { display: grid; grid-template-columns: 236px minmax(0, 1fr); min-height: calc(100vh - 52px); }
.cote {
  position: sticky; top: 52px; align-self: start;
  display: flex; flex-direction: column; gap: 1.25rem;
  height: calc(100vh - 52px); overflow-y: auto;
  padding: 1rem .75rem;
  background: var(--cote); color: var(--sur-cote);
}
.menu { display: flex; flex-direction: column; gap: 2px; }
.menu__entree {
  display: flex; align-items: center; gap: .65rem; width: 100%;
  padding: .55rem .7rem; border: 0; border-radius: 8px;
  background: transparent; color: var(--sur-cote); text-align: left; cursor: pointer;
  font-weight: 500;
}
.menu__entree:hover { background: var(--cote-survol); }
.menu__entree.est-active { background: var(--cote-actif); color: var(--sur-cote-actif); font-weight: 650; }
.menu__compte { margin-left: auto; min-width: 1.75rem; padding: 0 .4rem; border-radius: 999px; background: var(--cote-survol); font-size: .75rem; text-align: center; font-variant-numeric: tabular-nums; }
.menu__entree.est-active .menu__compte { background: rgb(0 0 0 / .14); }
.filtres { display: flex; flex-direction: column; gap: .7rem; padding-top: 1rem; border-top: 1px solid var(--cote-survol); }
.filtres:empty { display: none; }
.filtres__titre { font-size: .7rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--sur-cote-attenue); }
.filtre { display: flex; flex-direction: column; gap: .25rem; font-size: .75rem; color: var(--sur-cote-attenue); }
.filtre select, .filtre input { width: 100%; padding: .4rem .5rem; border: 1px solid transparent; border-radius: 6px; background: var(--surface); color: var(--texte); font-size: .8125rem; }
.cote__pied { margin-top: auto; color: var(--sur-cote-attenue); }
.cote .bouton--discret { color: var(--sur-cote); border-color: var(--cote-survol); }
.cote .bouton--discret:hover { background: var(--cote-survol); }

/* ---------- Contenu ---------- */
.contenu { display: flex; flex-direction: column; gap: 1.25rem; padding: 1.25rem 1.5rem 2rem; min-width: 0; }
.page-entete { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 1rem; }
.page-entete p { margin-top: .15rem; font-size: .8125rem; }

/* ---------- Boutons ---------- */
.bouton {
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  min-height: 34px; padding: 0 .85rem;
  border: 1px solid var(--primaire); border-radius: 7px;
  background: var(--primaire); color: var(--sur-primaire);
  font-weight: 600; font-size: .8125rem; cursor: pointer; white-space: nowrap;
  transition: background .15s, border-color .15s, color .15s;
}
.bouton:hover { background: var(--primaire-fonce); border-color: var(--primaire-fonce); }
.bouton .ic { width: 16px; height: 16px; }
.bouton--secondaire { background: var(--surface); color: var(--texte); border-color: var(--bordure-forte); }
.bouton--secondaire:hover { background: var(--survol); border-color: var(--bordure-forte); }
.bouton--discret { background: transparent; color: var(--lien); border-color: transparent; min-height: 28px; padding: 0 .5rem; }
.bouton--discret:hover { background: var(--survol); border-color: transparent; }
.bouton--plein { width: 100%; }
.bouton--icone { width: 32px; min-height: 32px; padding: 0; background: var(--surface); color: var(--texte); border-color: var(--bordure); }
.bouton--icone:hover { background: var(--survol); border-color: var(--bordure-forte); }
.bouton--danger { color: var(--danger); }
.bouton--danger-plein { background: var(--danger); border-color: var(--danger); color: var(--sur-danger); }
.bouton--danger-plein:hover { background: var(--danger); filter: brightness(.92); }
.bouton:disabled { opacity: .45; cursor: default; }
.retourne { display: inline-flex; transform: rotate(180deg); }
.lien { padding: 0; border: 0; background: none; color: var(--lien); font-weight: 500; cursor: pointer; text-align: left; }
.lien:hover { text-decoration: underline; }

.recherche { display: flex; align-items: center; gap: .4rem; height: 34px; padding: 0 .6rem; border: 1px solid var(--bordure-forte); border-radius: 7px; background: var(--surface); color: var(--texte-attenue); }
.recherche input { width: 13rem; border: 0; outline: 0; background: transparent; color: var(--texte); }
.recherche:focus-within { border-color: var(--anneau); box-shadow: 0 0 0 3px var(--anneau-doux); }

/* ---------- Panneaux ---------- */
.panneau { display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--bordure); border-radius: 10px; background: var(--surface); }
.panneau__entete { display: flex; align-items: center; justify-content: space-between; gap: .75rem; padding: .8rem 1rem; border-bottom: 1px solid var(--bordure); }
.panneau__corps { display: flex; flex-direction: column; gap: .6rem; padding: 1rem; }
.espace-travail { display: grid; grid-template-columns: minmax(0, 1fr) minmax(300px, 380px); gap: 1rem; align-items: start; }
.panneau--detail { position: sticky; top: 72px; max-height: calc(100vh - 92px); overflow-y: auto; }
.vide-bloc { padding: 2rem 1rem; text-align: center; color: var(--texte-attenue); }
.defile { overflow-x: auto; }

/* ---------- Tableaux ---------- */
.tableau { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.tableau th {
  position: sticky; top: 0;
  padding: .55rem .75rem; text-align: left; white-space: nowrap;
  background: var(--entete-tableau); color: var(--texte-attenue);
  font-size: .75rem; font-weight: 650; letter-spacing: .02em;
  border-bottom: 1px solid var(--bordure);
}
.tableau td { padding: .55rem .75rem; border-bottom: 1px solid var(--bordure); vertical-align: middle; }
.tableau tbody tr:last-child td { border-bottom: 0; }
.tableau tbody tr[data-action] { cursor: pointer; }
.tableau tbody tr[data-action]:hover { background: var(--survol); }
.tableau tbody tr.est-choisie { background: var(--choisie); box-shadow: inset 3px 0 0 var(--primaire); }
.tableau .nombre { text-align: right; }
.tableau .nombre, .tableau .serre { white-space: nowrap; }
.tableau--petit th, .tableau--petit td { padding: .4rem .6rem; font-size: .8125rem; }
.tri { padding: 0; border: 0; background: none; color: inherit; font: inherit; cursor: pointer; }
.tri:hover { color: var(--texte); }
.pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .75rem; padding: .6rem 1rem; border-top: 1px solid var(--bordure); font-size: .8125rem; }
.pagination__pas { display: flex; align-items: center; gap: .6rem; margin-left: auto; font-variant-numeric: tabular-nums; }

/* ---------- Pastilles (statuts) ---------- */
.pastille { display: inline-block; padding: .1rem .55rem; border-radius: 999px; font-size: .75rem; font-weight: 600; white-space: nowrap; }
.pastille--0 { background: var(--p0-fond); color: var(--p0-texte); }
.pastille--1 { background: var(--p1-fond); color: var(--p1-texte); }
.pastille--2 { background: var(--p2-fond); color: var(--p2-texte); }
.pastille--3 { background: var(--p3-fond); color: var(--p3-texte); }
.pastille--4 { background: var(--p4-fond); color: var(--p4-texte); }
.pastille--5 { background: var(--p5-fond); color: var(--p5-texte); }

/* ---------- Détail ---------- */
.detail { display: grid; grid-template-columns: 1fr 1fr; gap: .9rem 1rem; padding: 1rem; }
.detail__champ { min-width: 0; }
.detail__champ--large { grid-column: 1 / -1; }
.detail dt { font-size: .75rem; font-weight: 600; color: var(--texte-attenue); }
.detail dd { margin-top: .1rem; overflow-wrap: anywhere; }
.detail__lies { border-top: 1px solid var(--bordure); padding: .75rem 1rem 1rem; }
.detail__lies header { display: flex; align-items: center; justify-content: space-between; margin-bottom: .5rem; }
.detail__lies .tableau { border: 1px solid var(--bordure); border-radius: 8px; }

/* ---------- Tableau de bord ---------- */
.tuiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 1rem; }
.tuile {
  display: flex; flex-direction: column; gap: .2rem; padding: 1rem 1.1rem;
  border: 1px solid var(--bordure); border-radius: 10px; background: var(--surface);
  text-align: left; cursor: pointer; transition: border-color .15s, box-shadow .15s;
}
.tuile:hover:not(:disabled) { border-color: var(--primaire); box-shadow: 0 4px 14px -8px var(--primaire); }
.tuile:disabled { cursor: default; opacity: 1; }
.tuile__libelle { font-size: .8125rem; font-weight: 600; color: var(--texte-attenue); }
.tuile__valeur { font-family: var(--police-titre); font-size: 1.75rem; font-weight: 700; color: var(--texte); font-variant-numeric: tabular-nums; }
.tuile__detail { font-size: .75rem; color: var(--texte-attenue); }
.grille-accueil { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1rem; align-items: start; }
.panneau--large { grid-column: 1 / -1; }
.barre { display: grid; grid-template-columns: minmax(7rem, auto) 1fr 2rem; align-items: center; gap: .75rem; }
.barre__piste { height: 8px; border-radius: 999px; background: var(--survol); overflow: hidden; }
.barre__jauge { display: block; height: 100%; border-radius: inherit; }
.barre__jauge--0 { background: var(--p0-texte); }
.barre__jauge--1 { background: var(--p1-texte); }
.barre__jauge--2 { background: var(--p2-texte); }
.barre__jauge--3 { background: var(--p3-texte); }
.barre__jauge--4 { background: var(--p4-texte); }
.barre__jauge--5 { background: var(--p5-texte); }
.barre__n { text-align: right; font-variant-numeric: tabular-nums; color: var(--texte-attenue); }

/* ---------- Fenêtres ---------- */
.voile { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; padding: 1rem; background: rgb(15 20 30 / .45); }
.fenetre { display: flex; flex-direction: column; width: min(100%, 680px); max-height: calc(100vh - 2rem); border-radius: 12px; background: var(--surface); box-shadow: 0 24px 60px -20px rgb(0 0 0 / .45); }
.fenetre--petite { width: min(100%, 420px); }
.fenetre__entete { display: flex; align-items: center; justify-content: space-between; padding: 1rem 1.25rem; border-bottom: 1px solid var(--bordure); }
.fenetre__corps { padding: 1.25rem; overflow-y: auto; }
.fenetre__pied { display: flex; justify-content: flex-end; gap: .5rem; padding: .9rem 1.25rem; border-top: 1px solid var(--bordure); }
.grille-champs { display: grid; grid-template-columns: 1fr 1fr; gap: .9rem 1rem; }
.champ { display: flex; flex-direction: column; gap: .3rem; min-width: 0; }
.champ--large { grid-column: 1 / -1; }
.champ label { font-size: .8125rem; font-weight: 600; }
.champ input, .champ select, .champ textarea { width: 100%; padding: .5rem .65rem; border: 1px solid var(--bordure-forte); border-radius: 7px; background: var(--surface); color: var(--texte); }
.champ input:focus, .champ select:focus, .champ textarea:focus { outline: 0; border-color: var(--anneau); box-shadow: 0 0 0 3px var(--anneau-doux); }
.requis { color: var(--danger); }
.erreur { padding: 0 1.25rem; color: var(--danger); font-weight: 600; }
.erreur:empty { display: none; }

/* ---------- Annonce ---------- */
.annonce {
  position: fixed; right: 1.25rem; bottom: 1.25rem; z-index: 70;
  max-width: 24rem; padding: .7rem 1rem; border-radius: 8px;
  background: var(--texte); color: var(--fond); font-weight: 600;
  opacity: 0; transform: translateY(8px); pointer-events: none; transition: opacity .2s, transform .2s;
}
.annonce.est-visible { opacity: 1; transform: none; }
.annonce--grave { background: var(--danger); color: var(--sur-danger); }

/* ---------- Petits écrans ---------- */
@media (max-width: 1100px) {
  .espace-travail { grid-template-columns: minmax(0, 1fr); }
  .panneau--detail { position: static; max-height: none; }
}
@media (max-width: 820px) {
  .barre-haut__menu { display: inline-flex; }
  .barre-haut__date { display: none; }
  .cadre { grid-template-columns: minmax(0, 1fr); }
  .cote { position: fixed; top: 52px; left: 0; z-index: 40; width: 260px; transform: translateX(-100%); transition: transform .2s; }
  .menu-ouvert .cote { transform: none; box-shadow: 0 0 40px rgb(0 0 0 / .3); }
  .contenu { padding: 1rem; }
  .grille-champs, .detail { grid-template-columns: 1fr; }
  .recherche input { width: 9rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

